/**
 * Liest die strukturierte Gemini-Antwort aus und validiert
 * die Ticketdaten für die spätere Erstellung in Join.
 *
 * @returns {Array<{json: object}>} Validierte Ticketdaten
 */
const response = $input.first().json;
const source = $('Code in JavaScript1').first().json;
const rawText = response.candidates?.[0]?.content?.parts?.[0]?.text;

if (!rawText) {
  throw new Error(
    'Gemini hat keine auswertbare Textantwort geliefert.'
  );
}

const cleanedText = rawText
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let ticket;

try {
  ticket = JSON.parse(cleanedText);
} catch (error) {
  throw new Error(
    `Gemini-Antwort ist kein gültiges JSON: ${error.message}`
  );
}

const allowedCategories = [
  'Bug',
  'User Story',
  'Technical Task'
];

const allowedPriorities = [
  'urgent',
  'medium',
  'low'
];

if (!ticket.title || !ticket.description) {
  throw new Error(
    'Gemini-Antwort enthält keinen Titel oder keine Beschreibung.'
  );
}

if (!allowedCategories.includes(ticket.category)) {
  ticket.category = 'Technical Task';
}

if (!allowedPriorities.includes(ticket.priority)) {
  ticket.priority = 'medium';
}

/**
 * Ermittelt das heutige Datum in der Zeitzone Zürich.
 */
function getTodayInZurich() {
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Europe/Zurich',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric'
  }).formatToParts(new Date());

  const values = Object.fromEntries(
    parts.map(part => [part.type, part.value])
  );

  return {
    day: values.day,
    month: values.month,
    year: values.year,
    formatted: `${values.day}/${values.month}/${values.year}`,
    comparable: Number(
      `${values.year}${values.month}${values.day}`
    )
  };
}

/**
 * Prüft die Deadline.
 *
 * - Keine Deadline bleibt null.
 * - Ein ungültiges Datum wird auf heute gesetzt.
 * - Ein vergangenes Datum wird auf heute gesetzt.
 * - Gültige zukünftige Daten bleiben erhalten.
 */
function validateDeadline(value) {
  if (
    value === null ||
    value === undefined ||
    String(value).trim() === ''
  ) {
    return null;
  }

  const input = String(value).trim();
  const today = getTodayInZurich();

  let day;
  let month;
  let year;

  // DD/MM/YYYY, DD.MM.YYYY oder DD-MM-YYYY
  let match = input.match(
    /^(\d{1,2})[./-](\d{1,2})[./-](\d{4})$/
  );

  if (match) {
    day = match[1].padStart(2, '0');
    month = match[2].padStart(2, '0');
    year = match[3];
  } else {
    // YYYY-MM-DD
    match = input.match(
      /^(\d{4})-(\d{1,2})-(\d{1,2})$/
    );

    if (!match) {
      return today.formatted;
    }

    year = match[1];
    month = match[2].padStart(2, '0');
    day = match[3].padStart(2, '0');
  }

  const parsedDate = new Date(
    Date.UTC(
      Number(year),
      Number(month) - 1,
      Number(day)
    )
  );

  const isValid =
    parsedDate.getUTCFullYear() === Number(year) &&
    parsedDate.getUTCMonth() === Number(month) - 1 &&
    parsedDate.getUTCDate() === Number(day);

  if (!isValid) {
    return today.formatted;
  }

  const comparable = Number(`${year}${month}${day}`);

  if (comparable < today.comparable) {
    return today.formatted;
  }

  return `${day}/${month}/${year}`;
}

/**
 * Subtasks vereinheitlichen.
 * Unterstützt Strings und Objekte.
 * Es gibt keine Begrenzung auf zwei Subtasks.
 */
const subtasks = Array.isArray(ticket.subtasks)
  ? ticket.subtasks
      .map((subtask, index) => {
        const title =
          typeof subtask === 'string'
            ? subtask.trim()
            : String(
                subtask?.title ||
                subtask?.name ||
                subtask?.text ||
                ''
              ).trim();

        if (!title) {
          return null;
        }

        return {
          id: Date.now() + index + 1,
          title,
          completed: false
        };
      })
      .filter(Boolean)
  : [];

/**
 * Entfernt eine versehentlich zusätzlich ausgegebene
 * Subtask-Liste aus der Beschreibung.
 */
const description = String(ticket.description)
  .replace(
    /\s*(?:Subtasks?|Teilaufgaben|Aufgaben)\s*:\s*[\s\S]*$/i,
    ''
  )
  .trim();

return [
  {
    json: {
      sender: source.sender,
      subject: source.subject,
      body: source.body,
      title: String(ticket.title).trim(),
      description,
      category: ticket.category,
      priority: ticket.priority,
      deadline: validateDeadline(ticket.deadline),
      status: 'triage',
      creatorType: 'external',
      aiGenerated: true,
      subtasks
    }
  }
];

/**
 * Erstellt aus einer eingehenden E-Mail einen Prompt
 * für die strukturierte KI-Auswertung.
 *
 * @returns {Array<{json: object}>} E-Mail-Daten und KI-Prompt
 */
const email = $input.first().json;
const values = Object.values(email);

const sender =
  email.sender ??
  email.Sender ??
  email.Absender ??
  email.From ??
  email.from ??
  values[0] ??
  "";

const subject =
  email.subject ??
  email.Subject ??
  email.Subjekt ??
  email.Betreff ??
  values[1] ??
  "";

const body =
  email.body ??
  email.Body ??
  email.Körper ??
  email.Nachricht ??
  email.textPlain ??
  email.text ??
  email.snippet ??
  values[2] ??
  "";

/**
 * Aktuelles Datum für die Zeitzone Zürich ermitteln.
 */
const currentDate = new Intl.DateTimeFormat("de-CH", {
  timeZone: "Europe/Zurich",
  day: "2-digit",
  month: "2-digit",
  year: "numeric"
}).format(new Date());

const aiPrompt = `
Analysiere die folgende E-Mail und antworte ausschließlich mit gültigem JSON.

Das heutige Datum ist: ${currentDate}

Erforderliches Format:
{
  "title": "Kurzer prägnanter Titel",
  "description": "Bereinigte Ticketbeschreibung ohne Subtasks",
  "category": "Bug oder User Story oder Technical Task",
  "priority": "urgent oder medium oder low",
  "deadline": "DD/MM/YYYY oder null",
  "subtasks": [
    "Erster Subtask",
    "Zweiter Subtask"
  ]
}

Regeln:
- Kategorie muss Bug, User Story oder Technical Task sein.
- Priorität muss urgent, medium oder low sein.
- Übernimm eine Deadline nur, wenn in der E-Mail eine genannt wurde.
- Erfinde keine Deadline, wenn keine angegeben wurde.
- Eine Deadline darf niemals in der Vergangenheit liegen.
- Wenn eine angegebene Deadline ungültig ist oder in der Vergangenheit liegt, verwende das heutige Datum ${currentDate}.
- Verwende für die Deadline ausschließlich das Format DD/MM/YYYY.
- Extrahiere alle genannten Subtasks vollständig in das Array "subtasks".
- Es dürfen beliebig viele Subtasks vorhanden sein.
- Jeder Subtask muss ein eigener Eintrag im Array sein.
- Schreibe die Subtasks nicht zusätzlich in die Beschreibung.
- Wenn keine Subtasks genannt wurden, verwende ein leeres Array: [].
- Die Beschreibung soll nur die eigentliche Anfrage enthalten.
- Antworte ausschließlich mit dem JSON-Objekt und ohne Markdown.

Absender: ${sender}
Betreff: ${subject}
Nachricht: ${body}
`;

return [
  {
    json: {
      sender,
      subject,
      body,
      aiPrompt
    }
  }
];
